def _expansion(exponents: list[Expr], base_text: str) -> str | None:
    """Return the k-fold-product rewrite, or None when no product exists.

    `exponents` holds every level of a `(base^a)^b^...` tower.  A product
    exists only when every exponent is a concrete non-negative integer
    literal; a symbolic or negative exponent at any level means there is
    no finite rewrite to suggest.
    """
    total = 1
    for exp in exponents:
        k = _concrete_nonneg_int(exp)
        if k is None:
            return None
        total *= k
    if total == 0:
        return "1"
    if total == 1:
        return base_text
    return " * ".join([base_text] * total)

